// 현장관리_빈칸 › 빈칸고르기: 노트북이 POST site-gaps (사장님 열쇠) 로 부른다 (카톡 '비서' 4단계, 10/31).
// 현장관리 백업(Airtable)에서 오늘~days 일 안에 시작하고 A(공동현관·세대 비번·화장실)·B(필름 번호) 중 빈칸이 있거나
// 아직 답을 못 받은 업체 확인 질문(checks)이 있는 현장만.
// 비번 같은 값은 돌려주지 않는다 (빈칸 이름만).
const body = $('빈칸요청').first().json.body || {};
const seoul = new Date(Date.now() + 9 * 3600e3).toISOString().slice(0, 10);
const today = /^\d{4}-\d{2}-\d{2}$/.test(body.today || '') ? body.today : seoul;
const days = Math.min(Math.max(parseInt(body.days, 10) || 7, 0), 30);
const until = new Date(Date.parse(today + 'T00:00:00Z') + days * 864e5).toISOString().slice(0, 10);
const str = (v) => String(v == null ? '' : v).trim();
const clients = {};
for (const it of $('거래처읽기').all()) for (const r of (it.json.records || [])) {
  const f = r.fields || {};
  if (f.id) clients[f.id] = str(f['이름']);
}
// 업체 확인 질문 (2026-11-01) — 앱 설정(설정 표 data.checks). 앱에서 한 번도 안 고쳤으면 백업에 없으니 앱과 같은 기본 질문
const DEFAULT_CHECKS = [
  { id: 'door', text: '방문이 상하좌우 문틀에 닿는지 (닿으면 목수님 조정 부탁드려요)', ok: false },
  { id: 'overlap', text: '{날짜}에 겹치는 다른 공정', ok: false },
  { id: 'xmark', text: '현관문 부속교환할 부분에 마카펜으로 X 표시 부탁드려요', ok: true },
];
let checks = null;
for (const it of $('설정읽기').all()) for (const r of (it.json.records || [])) {
  try { const d = JSON.parse((r.fields || {}).data || '{}'); if (Array.isArray(d.checks)) checks = d.checks; } catch (e) { /* 다음 줄 */ }
}
checks = (checks || DEFAULT_CHECKS).filter((c) => c && str(c.id) && str(c.text) && !c.off).map((c) => ({ id: str(c.id), text: str(c.text), ok: !!c.ok }));
// 답을 받았거나 '이 현장은 안 물음'(skip, 11/1) 이면 묻지 않는다
const answered = (s, id) => { const a = (s.checks || {})[id]; return !!(a && typeof a === 'object' && a.skip) || !!str(a && typeof a === 'object' ? a.v : a); };
// 필름 주문 알림 (사장님 11/1) — 시공 orderDays(5)일 안이고 필름 단계가 아직 '필름 주문'(2) 전인 현장. 재고 없음·판매 중지까지 생각해 5일 전
const orderDays = Math.min(Math.max(parseInt(body.orderDays, 10) || 0, 0), 30);
const orderUntil = new Date(Date.parse(today + 'T00:00:00Z') + orderDays * 864e5).toISOString().slice(0, 10);
const last = until > orderUntil ? until : orderUntil;
// 주문 문자와 같은 모양 — 같은 번호는 한 번, 필요량은 ' + ' 로 (앱 Share.filmOrderText)
const orderFilms = (films) => {
  const seen = {}, order = [];
  (Array.isArray(films) ? films : []).filter((x) => x && str(x.code)).forEach((x) => {
    const k = str(x.code).replace(/\s+/g, ' ').toLowerCase();
    if (!seen[k]) { seen[k] = { code: str(x.code), qty: [] }; order.push(k); }
    if (str(x.qty) && !seen[k].qty.includes(str(x.qty))) seen[k].qty.push(str(x.qty));
  });
  return order.map((k) => ({ code: seen[k].code, qty: seen[k].qty.join(' + ') }));
};
const out = [], orders = [];
for (const it of $('현장읽기').all()) for (const r of (it.json.records || [])) {
  let s = {};
  try { s = JSON.parse((r.fields || {}).data || '{}'); } catch (e) { continue; }
  if (!s.id || s.hide) continue;
  const date = str(s.date).slice(0, 10);
  if (!date || date < today || date > last) continue;
  const name0 = str(s.name);
  const squash = (v) => v.replace(/\s+/g, '');
  const extra = [str(s.unit), str(s.size)].filter((v) => v && squash(name0).indexOf(squash(v)) === -1);
  const name = [name0].concat(extra).filter(Boolean).join(' ') || '(이름없음)';
  const client = clients[s.clientId] || clients[(r.fields || {})['거래처id']] || '';
  const stage = parseInt(s.filmStage, 10) || 0;
  if (orderDays && date <= orderUntil && stage < 2) orders.push({ id: s.id, client, name, date, stage, films: orderFilms(s.films) });
  if (date > until) continue;
  const missing = ['pwLobby', 'pwUnit', 'toilet'].filter((k) => !str(s[k]));
  if (!(Array.isArray(s.films) && s.films.some((x) => x && str(x.code)))) missing.push('films');
  const ask = checks.filter((c) => !answered(s, c.id));
  if (!missing.length && !ask.length) continue;
  // 👤 개인고객 (11/5): 업체방이 없다 — '카톡 방 없음' 알림 대신 앱 현장 화면의 [문자로 물어보기]
  if (client.replace(/\s+/g, '') === '개인고객') continue;
  out.push({ id: s.id, client, name, date, missing, checks: ask });
}
const byDate = (a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : 0);
out.sort(byDate); orders.sort(byDate);
return [{ json: { today, until, sites: out, orders } }];

// 현장관리_빈칸 › 우편함넣기: 노트북이 POST site-fill (사장님 열쇠) — 업체 답에서 뽑은 칸 값을 우편함(staticData)에 둔다.
// 현장관리 앱이 site-fill-take 로 가져가 그 기기 현장 칸에 바로 넣는다 (원본이 기기에 있어서, 10/31 사장님 '우편함').
const body = $input.first().json.body || {};
const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.fills = (sd.fills || []).filter((f) => now - f.t < 14 * 864e5);
const s = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const FIELDS = ['pwLobby', 'pwUnit', 'toilet'];
// 📋 업무 내역 (11/4): 우편함에 들어온 일을 값 없이 적는다 — 업무내역 worklog.js 가 앱에 보여 준다
sd.worklog = sd.worklog || [];
const LABEL = { pwLobby: '공동현관 비번', pwUnit: '세대 비번', toilet: '화장실' };
const logOf = (o, f) => {
  const put = f.update ? ' 바꿈' : ' 넣음';
  if (o.kind === 'field') return { kind: 'site', title: LABEL[o.field] + put, detail: o.room };
  if (o.kind === 'films') return { kind: 'site', title: '필름 번호' + put, detail: o.room };
  if (o.kind === 'check') return { kind: 'site', title: '업체 확인 답 받음', detail: o.room };
  if (o.kind === 'filmOrdered') return { kind: 'crew', title: '필름 주문 문자', detail: o.room + (o.value ? ' · ' + o.value : '') };
  if (o.kind === 'crewAdd') return { kind: 'crew', title: o.name + ' 인원 넣음', detail: o.date };
  if (o.kind === 'task') return { kind: 'site', title: '할 일 추가', detail: o.title };
  if (o.kind === 'done') return { kind: 'site', title: { pay: '잔금 받음', as: 'AS 완료', task: '할 일 완료' }[o.what], detail: '' };
  return null;
};
const srcOf = (o) => (o.room === '결재함' ? '결재함' : o.room === '인원 모집' ? '인원모집' : o.kind === 'filmOrdered' ? '필름 주문' : 'auto');
let n = 0;
for (const f of (Array.isArray(body.fills) ? body.fills : []).slice(0, 50)) {
  if (!f || typeof f !== 'object') continue;
  // 내역만 남기는 줄 — 앱 우편함에 넣지 않는다 (결재함 9시 실행 등, 11/4)
  if (f.kind === 'log') {
    if (s(f.title, 120)) sd.worklog.push({ id: 'l' + now.toString(36) + n, t: now, src: srcOf({ room: s(f.room, 40) }), kind: s(f.cat, 12) || 'crew', title: s(f.title, 120), detail: s(f.detail, 200), siteId: s(f.siteId, 40), state: f.state === 'need' ? 'need' : '', key: '' });
    n++;
    continue;
  }
  const o = { id: 'f' + now.toString(36) + n, t: now, siteId: s(f.siteId, 40), kind: f.kind, room: s(f.room, 40), at: s(f.at, 10) };
  if (!o.siteId) continue;
  if (o.kind === 'field') {
    o.field = FIELDS.includes(f.field) ? f.field : '';
    o.value = s(f.value, 300);
    if (!o.field || !o.value) continue;
  } else if (o.kind === 'films') {
    o.films = (Array.isArray(f.films) ? f.films : []).map((x) => ({ place: s(x && x.place, 40), code: s(x && x.code, 30) })).filter((x) => x.code).slice(0, 30);
    if (!o.films.length) continue;
  } else if (o.kind === 'check') {
    // 업체 확인 질문의 답 (2026-11-01)
    o.checkId = s(f.checkId, 40);
    o.value = s(f.value, 300);
    if (!o.checkId || !o.value) continue;
  } else if (o.kind === 'filmOrdered') {
    o.value = s(f.value, 300);   // 주문한 필름 'ps170 1롤 · px450 30m 이상'
  } else if (o.kind === 'crewAdd') {
    // 인원 모집 [넣기] (인원모집 흐름, 11/1) — 그날 인원에 이름
    o.date = s(f.date, 10); o.name = s(f.name, 20);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(o.date) || !o.name) continue;
  } else if (o.kind === 'task') {
    // 결재함 [내가할께] (업무일정표 흐름, 11/3) — 앱 할 일로. 현장과 상관없이 받는다 (siteId '-' 이면 현장 없음)
    o.title = s(f.title, 120); o.date = s(f.date, 10);
    if (!o.title || !/^\d{4}-\d{2}-\d{2}$/.test(o.date)) continue;
  } else if (o.kind === 'done') {
    // 결재함 [완료표시] (11/3): 잔금 받음·AS 완료·할 일 완료 → 앱 Kakao.fillPatch (11/4 고침: 전에는 여기서 버려져 앱에 안 들어갔다)
    o.what = ['pay', 'as', 'task'].includes(f.what) ? f.what : '';
    o.serviceId = s(f.serviceId, 60); o.taskId = s(f.taskId, 100);
    if (!o.what) continue;
  } else continue;   // 모르는 kind 는 버림. filmOrdered: 텔레그램 버튼으로 주문 문자를 보냄 → 앱 '필름 주문' 단계 (카톡_버튼, 11/1)
  sd.fills.push(o);
  const line = logOf(o, f);
  if (line) sd.worklog.push(Object.assign({ id: 'l' + now.toString(36) + n, t: now, src: srcOf(o), siteId: o.siteId === '-' ? '' : o.siteId, state: '', key: '' }, line));
  n++;
}
sd.worklog = sd.worklog.filter((x) => now - x.t < 90 * 864e5).slice(-2000);
return [{ json: { ok: true, n } }];

// 현장관리_빈칸 › 우편함꺼내기: 현장관리 앱이 POST site-fill-take (사장님 열쇠) {done:[번호]}.
// done 은 그 기기가 칸에 넣은 것 → 지운다. 남은 것을 모두 준다 (이 기기에 없는 현장은 앱이 건너뛰고 다른 기기를 기다린다). 14일 지나면 지움.
const body = $input.first().json.body || {};
const done = new Set((Array.isArray(body.done) ? body.done : []).map(String));
const sd = $getWorkflowStaticData('global');
const now = Date.now();
sd.fills = (sd.fills || []).filter((f) => !done.has(f.id) && now - f.t < 14 * 864e5);
return [{ json: { fills: sd.fills.map((f) => Object.assign({}, f)) } }];

// 현장관리_빈칸 › 내역: 📋 업무 내역 (사장님 11/4: 진행 내역을 한곳에) — POST work-log (사장님 열쇠).
// 우편함에 들어오는 일(필름 주문·인원·잔금·칸 넣기)은 우편함넣기가 여기 sd.worklog 에 함께 적는다. 앱 비서·노트북 답장은 add 로.
// add { items: [{ id?, t?, src, kind, title, detail?, siteId?, state?, key? }] } / list {} → 최근 500 / resolve { id | key } → 확인함
// 비번 값은 적지 않는다. 90일 · 2000건까지. 설계 docs/superpowers/specs/2026-11-04-업무내역-design.md
const body = $input.first().json.body || {};
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const s = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const keep = () => { sd.worklog = (sd.worklog || []).filter((x) => now - x.t < 90 * 864e5).slice(-2000); };
keep();
if (body.action === 'add') {
  let n = 0;
  const has = new Set(sd.worklog.map((x) => x.id));
  for (const it of (Array.isArray(body.items) ? body.items : []).slice(0, 200)) {
    if (!it || !s(it.title, 120)) continue;
    const id = s(it.id, 60) || 'w' + now.toString(36) + n;
    if (has.has(id)) continue;   // 옮기기를 다시 해도 두 번 안 들어가게
    const t = Number(it.t) > 0 && Number(it.t) <= now ? Number(it.t) : now;
    sd.worklog.push({ id, t, src: s(it.src, 12) || 'me', kind: s(it.kind, 12) || 'etc', title: s(it.title, 120), detail: s(it.detail, 200),
      siteId: s(it.siteId, 40), state: it.state === 'need' ? 'need' : '', key: s(it.key, 60) });
    has.add(id);
    n++;
  }
  sd.worklog.sort((a, b) => a.t - b.t);
  keep();
  return [{ json: { ok: true, n } }];
}
if (body.action === 'resolve') {
  const id = s(body.id, 60), key = s(body.key, 60);
  let n = 0;
  sd.worklog.forEach((x) => { if (x.state === 'need' && ((id && x.id === id) || (key && x.key === key))) { x.state = ''; n++; } });
  return [{ json: { ok: true, n } }];
}
return [{ json: { ok: true, items: sd.worklog.slice(-500).reverse().map((x) => ({ id: x.id, t: x.t, src: x.src, kind: x.kind, title: x.title, detail: x.detail, siteId: x.siteId, state: x.state })) } }];
